// OpenDotaServiceServer is the server API for OpenDotaService service.
// All implementations should embed UnimplementedOpenDotaServiceServer
// for forward compatibility.
//
// OpenDotaService exposes every GET/POST operation from the OpenDota OpenAPI spec.
//
// Request messages include explicit path params plus optional `query` and `body` structs.
// Responses use typed data messages derived from the OpenDota OpenAPI spec.
type OpenDotaServiceServer interface {
	// Benchmarks of average stat values for a hero
	GetBenchmarks(context.Context, *GetBenchmarksRequest) (*GetBenchmarksResponse, error)
	// Get static game data mirrored from the dotaconstants repository.
	GetConstantsResource(context.Context, *GetConstantsResourceRequest) (*GetConstantsResourceResponse, error)
	// Distributions of MMR data by bracket and country
	GetDistributions(context.Context, *GetDistributionsRequest) (*GetDistributionsResponse, error)
	// Submit arbitrary SQL queries to the database
	GetExplorer(context.Context, *GetExplorerRequest) (*GetExplorerResponse, error)
	// Finds recent matches by heroes played
	GetFindMatches(context.Context, *GetFindMatchesRequest) (*GetFindMatchesResponse, error)
	// Get service health data
	GetHealth(context.Context, *GetHealthRequest) (*GetHealthResponse, error)
	// Get stats about hero performance in recent matches
	GetHeroStats(context.Context, *GetHeroStatsRequest) (*GetHeroStatsResponse, error)
	// Get hero data
	GetHeroes(context.Context, *GetHeroesRequest) (*GetHeroesResponse, error)
	// Get hero performance over a range of match durations
	GetHeroDurations(context.Context, *GetHeroDurationsRequest) (*GetHeroDurationsResponse, error)
	// Get item popularity of hero categoried by start, early, mid and late game, analyzed from professional games
	GetHeroItemPopularity(context.Context, *GetHeroItemPopularityRequest) (*GetHeroItemPopularityResponse, error)
	// Get recent matches with a hero
	GetHeroMatches(context.Context, *GetHeroMatchesRequest) (*GetHeroMatchesResponse, error)
	// Get results against other heroes for a hero
	GetHeroMatchups(context.Context, *GetHeroMatchupsRequest) (*GetHeroMatchupsResponse, error)
	// Get players who have played this hero
	GetHeroPlayers(context.Context, *GetHeroPlayersRequest) (*GetHeroPlayersResponse, error)
	// Get league data
	GetLeagues(context.Context, *GetLeaguesRequest) (*GetLeaguesResponse, error)
	// Get data for a league
	GetLeague(context.Context, *GetLeagueRequest) (*GetLeagueResponse, error)
	// Get match IDs for a league (including amateur leagues)
	GetLeagueMatchIds(context.Context, *GetLeagueMatchIdsRequest) (*GetLeagueMatchIdsResponse, error)
	// Get matches for a league (excluding amateur leagues)
	GetLeagueMatches(context.Context, *GetLeagueMatchesRequest) (*GetLeagueMatchesResponse, error)
	// Get teams for a league
	GetLeagueTeams(context.Context, *GetLeagueTeamsRequest) (*GetLeagueTeamsResponse, error)
	// Get top currently ongoing live games
	GetLive(context.Context, *GetLiveRequest) (*GetLiveResponse, error)
	// Match data
	GetMatch(context.Context, *GetMatchRequest) (*GetMatchResponse, error)
	// Site metadata
	GetMetadata(context.Context, *GetMetadataRequest) (*GetMetadataResponse, error)
	// Get list of parsed match IDs
	GetParsedMatches(context.Context, *GetParsedMatchesRequest) (*GetParsedMatchesResponse, error)
	// Player data
	GetPlayer(context.Context, *GetPlayerRequest) (*GetPlayerResponse, error)
	// Counts in categories
	GetPlayerCounts(context.Context, *GetPlayerCountsRequest) (*GetPlayerCountsResponse, error)
	// Heroes played
	GetPlayerHeroes(context.Context, *GetPlayerHeroesRequest) (*GetPlayerHeroesResponse, error)
	// Distribution of matches in a single stat
	GetPlayerHistogramsField(context.Context, *GetPlayerHistogramsFieldRequest) (*GetPlayerHistogramsFieldResponse, error)
	// Matches played (full history, and supports column selection)
	GetPlayerMatches(context.Context, *GetPlayerMatchesRequest) (*GetPlayerMatchesResponse, error)
	// Players played with
	GetPlayerPeers(context.Context, *GetPlayerPeersRequest) (*GetPlayerPeersResponse, error)
	// Pro players played with
	GetPlayerPros(context.Context, *GetPlayerProsRequest) (*GetPlayerProsResponse, error)
	// Player hero rankings
	GetPlayerRankings(context.Context, *GetPlayerRankingsRequest) (*GetPlayerRankingsResponse, error)
	// Returns a history of the player rank tier/medal changes (replaces MMR)
	GetPlayerRatings(context.Context, *GetPlayerRatingsRequest) (*GetPlayerRatingsResponse, error)
	// Recent matches played (limited number of results)
	GetPlayerRecentMatches(context.Context, *GetPlayerRecentMatchesRequest) (*GetPlayerRecentMatchesResponse, error)
	// Refresh player match history (up to 500), medal (rank), and profile name
	PostPlayerRefresh(context.Context, *PostPlayerRefreshRequest) (*PostPlayerRefreshResponse, error)
	// Totals in stats
	GetPlayerTotals(context.Context, *GetPlayerTotalsRequest) (*GetPlayerTotalsResponse, error)
	// Wards placed in matches played
	GetPlayerWardmap(context.Context, *GetPlayerWardmapRequest) (*GetPlayerWardmapResponse, error)
	// Win/Loss count
	GetPlayerWinLoss(context.Context, *GetPlayerWinLossRequest) (*GetPlayerWinLossResponse, error)
	// Words said/read in matches played
	GetPlayerWordcloud(context.Context, *GetPlayerWordcloudRequest) (*GetPlayerWordcloudResponse, error)
	// Get list of pro matches
	GetProMatches(context.Context, *GetProMatchesRequest) (*GetProMatchesResponse, error)
	// Get list of pro players
	GetProPlayers(context.Context, *GetProPlayersRequest) (*GetProPlayersResponse, error)
	// Get list of randomly sampled public matches
	GetPublicMatches(context.Context, *GetPublicMatchesRequest) (*GetPublicMatchesResponse, error)
	// Top players by hero
	GetRankings(context.Context, *GetRankingsRequest) (*GetRankingsResponse, error)
	// Get top performances in a stat
	GetRecordsField(context.Context, *GetRecordsFieldRequest) (*GetRecordsFieldResponse, error)
	// Get parse request state
	GetRequestJobId(context.Context, *GetRequestJobIdRequest) (*GetRequestJobIdResponse, error)
	// Submit a new parse request. This call counts as 10 calls for rate limit (but not billing) purposes.
	PostRequestMatchId(context.Context, *PostRequestMatchIdRequest) (*PostRequestMatchIdResponse, error)
	// Win rates for certain item timings on a hero for items that cost at least 1400 gold
	GetScenariosItemTimings(context.Context, *GetScenariosItemTimingsRequest) (*GetScenariosItemTimingsResponse, error)
	// Win rates for heroes in certain lane roles
	GetScenariosLaneRoles(context.Context, *GetScenariosLaneRolesRequest) (*GetScenariosLaneRolesResponse, error)
	// Miscellaneous team scenarios
	GetScenariosMisc(context.Context, *GetScenariosMiscRequest) (*GetScenariosMiscResponse, error)
	// Get database schema
	GetSchema(context.Context, *GetSchemaRequest) (*GetSchemaResponse, error)
	// Search players by personaname.
	SearchPlayers(context.Context, *SearchPlayersRequest) (*SearchPlayersResponse, error)
	// Get team data
	GetTeams(context.Context, *GetTeamsRequest) (*GetTeamsResponse, error)
	// Get data for a team
	GetTeam(context.Context, *GetTeamRequest) (*GetTeamResponse, error)
	// Get heroes for a team
	GetTeamHeroes(context.Context, *GetTeamHeroesRequest) (*GetTeamHeroesResponse, error)
	// Get matches for a team
	GetTeamMatches(context.Context, *GetTeamMatchesRequest) (*GetTeamMatchesResponse, error)
	// Get players who have played for a team
	GetTeamPlayers(context.Context, *GetTeamPlayersRequest) (*GetTeamPlayersResponse, error)
	// Get list of highly ranked players
	GetTopPlayers(context.Context, *GetTopPlayersRequest) (*GetTopPlayersResponse, error)
}

